import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('compiles a static inputSchema once at register time and reuses it across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema: ToolDefinition['inputSchema'] = {
      type: 'object',
      properties: {query: {type: 'string'}},
      required: ['query'],
    };
    const definition: ToolDefinition = {
      name: 'search_docs',
      description: 'Search documentation',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async () => 'ok');
    const readsAtRegister = schemaReads;

    for (let i = 0; i < 10; i++) {
      await registry.execute('search_docs', {query: 'hal'});
    }

    const registerFailureMessage = await Promise.resolve()
      .then(() =>
        registry.register(
          {
            name: 'broken_tool',
            description: 'Has an invalid schema',
            inputSchema: {
              type: 'not-a-json-schema-type',
              properties: {},
            },
          },
          async () => 'unreachable'
        )
      )
      .then(() => 'returned without throwing')
      .catch((error: Error) => error.message);

    expect({
      readsAtRegister,
      readsAfterTenExecutes: schemaReads,
      mentionsBrokenTool: registerFailureMessage.includes('broken_tool'),
    }).toEqual({
      readsAtRegister: 1,
      readsAfterTenExecutes: 1,
      mentionsBrokenTool: true,
    });
  });

  it('rejects input missing a required property or carrying a wrong-typed property without calling the executor or leaking values', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const emptyCallResponse = await registry.execute('get_weather', {});
    const wrongTypeResponse = await registry.execute('get_weather', {location: 987654321});

    expect({
      executorCalls,
      emptyMentionsField: emptyCallResponse.result.includes('location'),
      emptyMentionsRequired: /required/i.test(emptyCallResponse.result),
      wrongTypeMentionsField: wrongTypeResponse.result.includes('location'),
      wrongTypeMentionsExpectedType: wrongTypeResponse.result.includes('string'),
      leaksValueInResult: wrongTypeResponse.result.includes('987654321'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      emptyMentionsField: true,
      emptyMentionsRequired: true,
      wrongTypeMentionsField: true,
      wrongTypeMentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });
});

import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

const ajv = new Ajv({
  allErrors: true,
  format: false,
  unknownFormats: 'ignore',
  strictKeywords: false,
  strictDefaults: false,
  coerceTypes: false,
  useDefaults: false,
  addUsedSchema: false,
  logger: false,
});

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<ToolDefinition['inputSchema'], ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    if (typeof definition === 'function') {
      const resolved = definition();
      this.tools.set(resolved.name, {definitionSource: definition, execute});
      return;
    }

    const validator = compileInputSchema(definition.name, definition.inputSchema);
    this.tools.set(definition.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input before running the tool; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = this.resolveValidator(name, tool);
    if (!validator(input)) {
      const failures = formatValidationErrors(validator.errors ?? []);
      log.warn('tool', 'input validation failed', {name, failures});
      return {result: `Invalid input for tool "${name}": ${failures.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(name: string, tool: StoredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const compiled = compileInputSchema(name, schema);
    this.dynamicValidators.set(schema, compiled);
    return compiled;
  }
}

function compileInputSchema(toolName: string, schema: ToolDefinition['inputSchema']): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`, {cause: error});
  }
}

function formatValidationErrors(errors: ErrorObject[]): string[] {
  if (errors.length === 0) return ['input: failed schema validation'];
  return errors.map(formatValidationError);
}

function formatValidationError(error: ErrorObject): string {
  if (error.keyword === 'required' && 'missingProperty' in error.params) {
    return `${appendPath(error.dataPath, String(error.params.missingProperty))}: required property is missing`;
  }
  const fieldPath = error.dataPath.replace(/^\./, '') || 'input';
  return `${fieldPath}: ${error.message ?? error.keyword}`;
}

function appendPath(dataPath: string, property: string): string {
  const prefix = dataPath.replace(/^\./, '');
  return prefix ? `${prefix}.${property}` : property;
}

